      "content": "{\n  \"name\": \"dsh-plugin-nlbi\",\n  \"version\": \"0.2.1\",\n  \"description\": \"自然语言查询 + 商业智能报表插件 for DeepSeek Harness：在 dsh-mysql 连接底座之上，提供 Text2SQL 自然语言查库、15+ 图表类型、Dashboard 仪表盘、指标/维度管理、多维分析、自助分析、报表导出、审计日志与数据权限。Natural-language data queries + enterprise BI reports for DeepSeek Harness: Text2SQL, 15+ chart types, dashboards, metric management, multi-dimensional analysis, self-service analysis, export, audit log and data permissions.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./typert\": {\n      \"default\": \"./lib/typert.host.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/shared.js\",\n    \"lib/sqlsafe.js\",\n    \"lib/text2sql.js\",\n    \"lib/chart.js\",\n    \"lib/metrics.js\",\n    \"lib/dashboard.js\",\n    \"lib/export.js\",\n    \"lib/typert.host.js\",\n    \"lib/client.js\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"test/fixtures/dsh_test.sql\",\n    \"test/fixtures/README.md\",\n    \"LICENSE\",\n    \"NOTICE\"\n  ],\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"nlbi\",\n    \"text2sql\",\n    \"nl2sql\",\n    \"bi\",\n    \"dashboard\",\n    \"metrics\",\n    \"olap\",\n    \"mysql\",\n    \"database\",\n    \"sql\",\n    \"chart\",\n    \"echarts\",\n    \"report\",\n    \"export\",\n    \"audit\",\n    \"tools\",\n    \"connector\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"1byteone <yjs_0831@qq.com>\",\n  \"homepage\": \"https://github.com/1byteone/dsh-plugin-nlbi#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/1byteone/dsh-plugin-nlbi.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/1byteone/dsh-plugin-nlbi/issues\"\n  },\n  \"dependencies\": {\n    \"mysql2\": \"^3.11.0\",\n    \"node-sql-parser\": \"^5.4.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node scripts/run-tests.mjs\",\n    \"test:unit\": \"node scripts/run-tests.mjs --unit\",\n    \"check\": \"node scripts/run-tests.mjs --check\"\n  }\n}\n"
